class Qwen3_5MoeMLP(nn.Module):
    """Official Qwen3.5-MoE SwiGLU MLP for the shared expert branch.

    Parameters:
        config: Qwen3.5-MoE text configuration.
        intermediate_size: Width of the particular MLP branch.
    """

    def __init__(self, config: Qwen3_5MoeTextConfig, intermediate_size: int) -> None:
        """Create the source gate, up, and down projections.

        Parameters:
            config: Qwen3.5-MoE text configuration.
            intermediate_size: Width of the particular MLP branch.
        """
        super().__init__()
        self.gate_proj = nn.Linear(config.hidden_size, intermediate_size, bias = False)
        self.up_proj = nn.Linear(config.hidden_size, intermediate_size, bias = False)
        self.down_proj = nn.Linear(intermediate_size, config.hidden_size, bias = False)

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        """Apply SwiGLU feed-forward computation.

        Parameters:
            hidden_states: Input tensor whose trailing size is hidden size.
        """
        return self.down_proj(F.silu(self.gate_proj(hidden_states)) * self.up_proj(hidden_states))


class Qwen3_5MoeExperts(nn.Module):
    """Collection of expert weights stored as 3D tensors.

    Parameters:
        config: Qwen3.5-MoE text configuration.
    """

    def __init__(self, config: Qwen3_5MoeTextConfig) -> None:
        """Create packed source expert gate/up and down tensors.

        Parameters:
            config: Qwen3.5-MoE text configuration.
        """
        super().__init__()
        self.num_experts = config.num_experts
        self.hidden_dim = config.hidden_size
        self.intermediate_dim = config.moe_intermediate_size
        self.gate_up_proj = nn.Parameter(torch.empty(self.num_experts, 2 * self.intermediate_dim, self.hidden_dim))
        self.down_proj = nn.Parameter(torch.empty(self.num_experts, self.hidden_dim, self.intermediate_dim))

    def forward(
        self,
        hidden_states: torch.Tensor,
        top_k_index: torch.Tensor,
        top_k_weights: torch.Tensor,
    ) -> torch.Tensor:
        """Dispatch flattened token states to selected packed experts.

        Parameters:
            hidden_states: Flattened token states.
            top_k_index: Selected expert IDs per token.
            top_k_weights: Selected normalized routing scores.
        """
        final_hidden_states = torch.zeros_like(hidden_states)
        with torch.no_grad():
            expert_mask = F.one_hot(top_k_index, num_classes = self.num_experts).permute(2, 1, 0)
            expert_hit = torch.greater(expert_mask.sum(dim = (-1, -2)), 0).nonzero()
        for expert_idx in expert_hit:
            index = expert_idx[0]
            top_k_pos, token_idx = torch.where(expert_mask[index])
            current_state = hidden_states[token_idx]
            gate, up = F.linear(current_state, self.gate_up_proj[index]).chunk(2, dim = -1)
            current_hidden_states = F.linear(F.silu(gate) * up, self.down_proj[index])
            current_hidden_states = current_hidden_states * top_k_weights[token_idx, top_k_pos, None]
            final_hidden_states.index_add_(0, token_idx, current_hidden_states.to(final_hidden_states.dtype))
        return final_hidden_states


class Qwen3_5MoeTopKRouter(nn.Module):
    """Official always-normalized softmax top-k router.

    Parameters:
        config: Qwen3.5-MoE text configuration.
    """

    def __init__(self, config: Qwen3_5MoeTextConfig) -> None:
        """Create source router weight matrix.

        Parameters:
            config: Qwen3.5-MoE text configuration.
        """
        super().__init__()
        self.top_k = config.num_experts_per_tok
        self.num_experts = config.num_experts
        self.hidden_dim = config.hidden_size
        self.weight = nn.Parameter(torch.zeros(self.num_experts, self.hidden_dim))

    def forward(self, hidden_states: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        """Compute router logits, normalized top-k weights, and expert IDs.

        Parameters:
            hidden_states: Token states whose trailing dimension is hidden size.
        """
        hidden_states = hidden_states.reshape(-1, self.hidden_dim)
        router_logits = F.linear(hidden_states, self.weight)  # (seq_len, num_experts)
        router_probs = F.softmax(router_logits, dtype = torch.float, dim = -1)
        router_top_value, router_indices = torch.topk(router_probs, self.top_k, dim = -1)
        router_top_value /= router_top_value.sum(dim = -1, keepdim = True)
        return router_logits, router_top_value.to(router_logits.dtype), router_indices


class Qwen3_5MoeSparseMoeBlock(nn.Module):
    """Official routed experts plus gated always-active shared expert.

    Parameters:
        config: Qwen3.5-MoE text configuration.
    """

    def __init__(self, config: Qwen3_5MoeTextConfig) -> None:
        """Create router, packed experts, and shared expert branch.

        Parameters:
            config: Qwen3.5-MoE text configuration.
        """
        super().__init__()
        self.gate = Qwen3_5MoeTopKRouter(config)
        self.experts = Qwen3_5MoeExperts(config)
        self.shared_expert = Qwen3_5MoeMLP(config, config.shared_expert_intermediate_size)
        self.shared_expert_gate = nn.Linear(config.hidden_size, 1, bias = False)

    def forward(self, hidden_states: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
        """Compute routed and shared expert outputs and retain router logits.

        Parameters:
            hidden_states: States shaped ``[batch, sequence, hidden_size]``.
        """
        batch_size, sequence_length, hidden_dim = hidden_states.shape
        flattened_states = hidden_states.view(-1, hidden_dim)
        shared_expert_output = self.shared_expert(flattened_states)
        router_logits, routing_weights, selected_experts = self.gate(flattened_states)
        expert_output = self.experts(flattened_states, selected_experts, routing_weights)
        shared_expert_output = torch.sigmoid(self.shared_expert_gate(flattened_states)) * shared_expert_output
        return (expert_output + shared_expert_output).reshape(batch_size, sequence_length, hidden_dim), router_logits


