class Qwen3_5MoeDecoderLayer(nn.Module):
    """Official hybrid Qwen3.5-MoE decoder layer with routed MLP.

    Parameters:
        config: Qwen3.5-MoE text configuration.
        layer_idx: Decoder layer index.
    """

    def __init__(self, config: Qwen3_5MoeTextConfig, layer_idx: int) -> None:
        """Create configured token mixer, source norms, and sparse MoE block.

        Parameters:
            config: Qwen3.5-MoE text configuration.
            layer_idx: Decoder layer index.
        """
        super().__init__()
        self.block_type = config.layer_types[layer_idx]
        if self.block_type == "linear_attention":
            self.linear_attn = Qwen3_5MoeGatedDeltaNet(config, layer_idx)
        elif self.block_type == "full_attention":
            self.self_attn = Qwen3_5MoeAttention(config, layer_idx)
        else:
            raise ValueError(f"Unsupported Qwen3.5-MoE layer type: {self.block_type}")
        self.mlp = Qwen3_5MoeSparseMoeBlock(config)
        self.input_layernorm = Qwen3_5RMSNorm(config.hidden_size, eps = config.rms_norm_eps)
        self.post_attention_layernorm = Qwen3_5RMSNorm(config.hidden_size, eps = config.rms_norm_eps)

    def forward(
        self,
        hidden_states: torch.Tensor,
        position_embeddings: tuple[torch.Tensor, torch.Tensor],
        attention_mask: torch.Tensor | None,
        past_key_values: Qwen3_5Cache | None,
        use_cache: bool,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        """Apply hybrid token mixer, routed experts, and residual connections.

        Parameters:
            hidden_states: Decoder input states.
            position_embeddings: Partial RoPE values for full-attention layers.
            attention_mask: Optional valid-token mask.
            past_key_values: Optional hybrid K/V and recurrent cache.
            use_cache: Whether cache state is updated.
        """
        residual = hidden_states
        hidden_states = self.input_layernorm(hidden_states)
        # Token Mixer
        if self.block_type == "linear_attention":
            hidden_states = self.linear_attn(hidden_states, past_key_values, attention_mask)
        else:
            hidden_states = self.self_attn(hidden_states, position_embeddings, attention_mask, past_key_values, use_cache)
        hidden_states = residual + hidden_states
        # Fully Connected
        moe_output, router_logits = self.mlp(self.post_attention_layernorm(hidden_states))
        return hidden_states + moe_output, router_logits


class Qwen3_5MoeTextModel(nn.Module):
    """Framework-independent Qwen3.5-MoE text decoder.

    Parameters:
        config: Qwen3.5-MoE text configuration.
    """

    def __init__(self, config: Qwen3_5MoeTextConfig) -> None:
        """Create embeddings, hybrid MoE decoder layers, final norm, and RoPE.

        Parameters:
            config: Qwen3.5-MoE text configuration.
        """
        super().__init__()
        self.config = config
        self.embed_tokens = nn.Embedding(config.vocab_size, config.hidden_size, config.pad_token_id)
        self.layers = nn.ModuleList([Qwen3_5MoeDecoderLayer(config, index) for index in range(config.num_hidden_layers)])
        self.norm = Qwen3_5RMSNorm(config.hidden_size, eps = config.rms_norm_eps)
        self.rotary_emb = Qwen3_5RotaryEmbedding(config)

    def forward(
        self,
        input_ids: torch.Tensor,
        attention_mask: torch.Tensor | None = None,
        past_key_values: Qwen3_5Cache | None = None,
        use_cache: bool | None = None,
    ) -> tuple[torch.Tensor, Qwen3_5Cache | None, tuple[torch.Tensor, ...]]:
        """Return final hidden states, optional cache, and per-layer router logits.

        Parameters:
            input_ids: Text token IDs.
            attention_mask: Optional valid-token mask.
            past_key_values: Optional hybrid cache from an earlier forward call.
            use_cache: Whether cache state is created and updated.
        """
        use_cache = self.config.use_cache if use_cache is None else use_cache
        if use_cache and past_key_values is None:
            past_key_values = Qwen3_5Cache()
        hidden_states = self.embed_tokens(input_ids)
        past_length = past_key_values.get_seq_length() if past_key_values is not None else 0
        position_ids = torch.arange(past_length, past_length + input_ids.shape[1], device = input_ids.device)
        position_ids = position_ids.unsqueeze(0).expand(input_ids.shape[0], -1)
        position_embeddings = self.rotary_emb(hidden_states, position_ids)
        router_logits = []
        for layer in self.layers:
            hidden_states, layer_router_logits = layer(
                hidden_states,
                position_embeddings,
                attention_mask,
                past_key_values,
                use_cache,
            )
            router_logits.append(layer_router_logits)
        if past_key_values is not None and use_cache:
            past_key_values.sequence_length += input_ids.shape[1]
        return self.norm(hidden_states), past_key_values if use_cache else None, tuple(router_logits)


class Qwen3_5MoeForCausalLM(nn.Module):
    """Qwen3.5-MoE causal LM with auxiliary router load-balancing loss.

    Parameters:
        config: Qwen3.5-MoE text configuration.
    """

    def __init__(self, config: Qwen3_5MoeTextConfig) -> None:
        """Create source hybrid MoE text model and untied LM head.

        Parameters:
            config: Qwen3.5-MoE text configuration.
        """
        super().__init__()
        self.config = config
        self.model = Qwen3_5MoeTextModel(config)
        self.lm_head = nn.Linear(config.hidden_size, config.vocab_size, bias = False)
        self.apply(self._init_weights)

    def _init_weights(self, module: nn.Module) -> None:
        """Initialize source projections, norms, routers, and packed experts.

        Parameters:
            module: Module visited during recursive initialization.
        """
        if isinstance(module, (nn.Linear, nn.Embedding, nn.Conv1d)):
            nn.init.normal_(module.weight, mean = 0.0, std = self.config.initializer_range)
            if getattr(module, "bias", None) is not None:
                nn.init.zeros_(module.bias)
        elif isinstance(module, Qwen3_5MoeExperts):
            nn.init.normal_(module.gate_up_proj, mean = 0.0, std = self.config.initializer_range)
            nn.init.normal_(module.down_proj, mean = 0.0, std = self.config.initializer_range)
        elif isinstance(module, Qwen3_5RMSNorm):
            nn.init.zeros_(module.weight)

    def forward(
        self,
        input_ids: torch.Tensor,
        attention_mask: torch.Tensor | None = None,
        past_key_values: Qwen3_5Cache | None = None,
        use_cache: bool | None = None,
        labels: torch.Tensor | None = None,
        output_router_logits: bool | None = None,
    ) -> MoeCausalLMOutput:
        """Return logits, CE plus router auxiliary loss, cache, and diagnostics.

        Parameters:
            input_ids: Text token IDs.
            attention_mask: Optional valid-token mask.
            past_key_values: Optional hybrid cache.
            use_cache: Whether cache state is returned.
            labels: Optional shifted language-model labels.
            output_router_logits: Whether per-layer router logits are returned.
        """
        output_router_logits = self.config.output_router_logits if output_router_logits is None else output_router_logits
        hidden_states, cache, router_logits = self.model(input_ids, attention_mask, past_key_values, use_cache)
        logits = self.lm_head(hidden_states)
        loss = aux_loss = None
        if labels is not None:
            loss = F.cross_entropy(logits[:, :-1].reshape(-1, self.config.vocab_size), labels[:, 1:].reshape(-1), ignore_index = -100)
            aux_loss = load_balancing_loss(router_logits, self.config.num_experts, self.config.num_experts_per_tok, attention_mask)
            loss = loss + self.config.router_aux_loss_coef * aux_loss
        return MoeCausalLMOutput(
            logits = logits,
            loss = loss,
            aux_loss = aux_loss,
            past_key_values = cache,
            router_logits = router_logits if output_router_logits else None,
        )


